    calculateIodateOutcome(input, index) {
        const val = parseFloat(input.value);
        const select = document.querySelector(`select[name="test_outcome_${index}"]`);
        if (!select) return;
        if (isNaN(val)) {
            select.value = "";
        } else if (val >= 20 && val <= 40) {
            select.value = "ผ่าน";
        } else {
            select.value = "ไม่ผ่าน";
        }
    },

